contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 amount) public {
        require(amount > 0 && amount <= 1e30);
        // collateral()/debt() point at this test contract (set below via constructor arg trick not available,
        // so instead we call requestLoan directly; its token interactions go through fallback returning success).
        uint256 id = c.requestLoan(amount, 1e18, 1e18, 1 days);
        assert(id == 0 && c.isActive(0) && c.getRequest(0).amount == amount && c.getRequest(0).active);
    }
    fallback() external payable {
        // Emulate ERC20 token responses: return 32-byte true for transferFrom/transfer/approve,
        // 0 for decimals(), etc. Non-empty 32-byte data satisfies SafeTransferLib checks.
        assembly {
            let ptr := mload(0x40)
            mstore(ptr, 1)
            // for decimals() (selector 0x313ce567) return 18
            if eq(shr(224, calldataload(0)), 0x313ce567) {
                mstore(ptr, 18)
            }
            return(ptr, 32)
        }
    }
    receive() external payable {}
}

