contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address collateral_, uint256 amount_, uint256 duration_) public {
        require(duration_ > 0);
        // request a loan with 0 interest rate and loanToCollateral = 1 so no real token is needed
        uint256 reqID = c.requestLoan(amount_, 0, 1, duration_);
        require(reqID == 0);
        require(c.isActive(reqID));

        uint256 loanID = c.clearRequest(reqID, false, false);

        C.Loan memory loan = c.getLoan(loanID);
        C.Request memory req = c.getRequest(reqID);

        assert(
            !c.isActive(reqID) &&
            !req.active &&
            loan.lender == address(this) &&
            loan.amount == amount_ &&
            loan.expiry == block.timestamp + duration_ &&
            loan.collateral == amount_ &&
            loan.unclaimed == 0
        );
    }
    receive() external payable {}
}

